tool_schemas.implementation:
def list_databases(workspace_id=None, parent_page_id=None, archived=None, status=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "list-databases",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        # Basic per-workspace per-minute limit if logs exist: 120/min
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    ws_pat = re.compile(r"^ntn_[a-z]+_[0-9A-HJKMNP-TV-Z]{10,}$|^ntn_ws_[0-9A-HJKMNP-TV-Z]{10,}$")
    pg_pat = re.compile(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$")

    if workspace_id is not None and (not isinstance(workspace_id, str) or not ws_pat.match(workspace_id)):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")

    if parent_page_id is not None and (not isinstance(parent_page_id, str) or not pg_pat.match(parent_page_id)):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "parent_page_id"})
        return _err("VALIDATION_ERROR", "parent_page_id is malformed.", field="parent_page_id")

    if archived is not None and not isinstance(archived, bool):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "archived"})
        return _err("VALIDATION_ERROR", "archived must be boolean.", field="archived")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived.", field="status")
        if archived is not None:
            # conflict rule: archived flag must match status
            if (archived is True and status != "archived") or (archived is False and status != "active"):
                _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "archived and status conflict.")

    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "title"):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "sort_by"})
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, title.", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "sort_order"})
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.", field="sort_order")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Determine ambient workspace if not specified (pick any existing workspace)
    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    if workspace_id is None:
        # pick a workspace that actually has databases
        ws_set = []
        for d in dbs:
            if isinstance(d, dict) and d.get("workspace_id"):
                ws_set.append(d.get("workspace_id"))
        workspace_id = ws_set[0] if ws_set else None

    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    # Filter
    out = []
    for d in dbs:
        if not isinstance(d, dict):
            continue
        if workspace_id is not None and d.get("workspace_id") != workspace_id:
            continue
        # schema doesn't include deleted for databases; keep check for robustness
        if d.get("status") == "deleted":
            continue
        if parent_page_id is not None and d.get("parent_page_id") != parent_page_id:
            continue
        if status is not None and d.get("status") != status:
            continue
        if archived is not None and bool(d.get("archived")) != archived:
            continue
        # Typical API filters out archived unless explicitly requested.
        if archived is None and status is None and d.get("status") == "archived":
            continue
        out.append(d)

    # Sort
    reverse = (sort_order == "desc")

    def _key_title(d):
        v = d.get("title")
        return ("" if v is None else str(v).lower(), d.get("id") or "")

    def _key_dtfield(d, field):
        dt = _parse_dt(d.get(field) or "")
        # Put missing dates last
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, d.get("id") or "")

    if sort_by == "title":
        out.sort(key=_key_title, reverse=reverse)
    elif sort_by == "created_at":
        out.sort(key=lambda d: _key_dtfield(d, "created_at"), reverse=reverse)
    else:
        out.sort(key=lambda d: _key_dtfield(d, "updated_at"), reverse=reverse)

    # Pagination cursor (opaque-ish): "v1:<sort_by>:<primary_value>:<id>"
    start_idx = 0
    if cursor:
        if not cursor.startswith("v1:"):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        parts = cursor.split(":", 3)
        if len(parts) != 4:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        _, c_sort, c_val, c_id = parts
        if c_sort != sort_by:
            # allow but treat as invalid to preserve stable pagination contract
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

        def _match_after(d):
            did = d.get("id") or ""
            if sort_by == "title":
                dv = ("" if d.get("title") is None else str(d.get("title")).lower())
                cv = c_val.lower()
                if reverse:
                    return (dv, did) < (cv, c_id)
                return (dv, did) > (cv, c_id)
            else:
                dt = _parse_dt(d.get(sort_by) or "")
                cdt = _parse_dt(c_val)
                if dt is None or cdt is None:
                    return False
                tup = (dt, did)
                ctup = (cdt, c_id)
                if reverse:
                    return tup < ctup
                return tup > ctup

        # find first element after cursor
        found = False
        for i, d in enumerate(out):
            if _match_after(d):
                start_idx = i
                found = True
                break
        if not found:
            start_idx = len(out)

    page = out[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(out)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        if sort_by == "title":
            last_val = ("" if last.get("title") is None else str(last.get("title")).lower())
        else:
            last_val = last.get(sort_by) or ""
        next_cursor = f"v1:{sort_by}:{last_val}:{last.get('id') or ''}"

    resp = {"results": page, "total": len(out), "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", workspace=workspace_id, meta={"returned": len(page), "total": len(out)})
    return resp

def query_database(database_id, filter=None, sorts=None, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status_code, latency_ms, workspace_id_used=None, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, workspace_id_used):
        quotas = _load("quotas.json")
        usage = _load("usage_counters.json")
        logs = _load("request_logs.json")
        if not isinstance(quotas, list):
            quotas = []
        if not isinstance(usage, list):
            usage = []
        if not isinstance(logs, list):
            logs = []

        q = None
        for r in quotas:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == workspace_id_used and r.get("endpoint") == endpoint and r.get("active") is True:
                q = r
                break

        now = datetime.datetime.utcnow()
        if q:
            rpm = q.get("rate_limit_per_minute")
            if isinstance(rpm, int) and rpm >= 0:
                cutoff = now - datetime.timedelta(seconds=60)
                c = 0
                for lr in logs:
                    if not isinstance(lr, dict):
                        continue
                    if lr.get("workspace_id") != workspace_id_used:
                        continue
                    if lr.get("endpoint") != endpoint:
                        continue
                    ts = _parse_dt(lr.get("timestamp"))
                    if ts and ts >= cutoff:
                        c += 1
                if c >= rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")

            cap = q.get("quota_per_day")
            if isinstance(cap, int) and cap >= 0:
                day = now.date().isoformat()
                urow = None
                for ur in usage:
                    if isinstance(ur, dict) and ur.get("workspace_id") == workspace_id_used and ur.get("endpoint") == endpoint and ur.get("day") == day:
                        urow = ur
                        break
                used = urow.get("count", 0) if isinstance(urow, dict) else 0
                if isinstance(used, int) and used >= cap:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _get_prop_value(page, prop_name):
        props = page.get("properties")
        if not isinstance(props, dict):
            return None
        return props.get(prop_name)

    def _extract_sortable(v):
        # Best-effort extraction from Notion-like property values
        if v is None:
            return None
        if isinstance(v, (int, float, bool, str)):
            return v
        if isinstance(v, dict):
            # common types
            if "number" in v and isinstance(v.get("number"), (int, float)):
                return v.get("number")
            if "checkbox" in v and isinstance(v.get("checkbox"), bool):
                return v.get("checkbox")
            if "date" in v and isinstance(v.get("date"), dict):
                d = v["date"].get("start")
                if isinstance(d, str):
                    dt = _parse_dt(d)
                    return dt or d
            if "select" in v and isinstance(v.get("select"), dict):
                name = v["select"].get("name")
                if isinstance(name, str):
                    return name
            if "status" in v and isinstance(v.get("status"), dict):
                name = v["status"].get("name")
                if isinstance(name, str):
                    return name
            if "title" in v and isinstance(v.get("title"), list):
                # concatenate plain_text
                parts = []
                for it in v["title"]:
                    if isinstance(it, dict):
                        pt = it.get("plain_text")
                        if isinstance(pt, str):
                            parts.append(pt)
                return "".join(parts)
            if "rich_text" in v and isinstance(v.get("rich_text"), list):
                parts = []
                for it in v["rich_text"]:
                    if isinstance(it, dict):
                        pt = it.get("plain_text")
                        if isinstance(pt, str):
                            parts.append(pt)
                return "".join(parts)
        if isinstance(v, list):
            return len(v)
        return str(v)

    def _apply_filter(pages_rows, flt):
        # Minimal subset: AND/OR, property equals/contains, timestamp comparisons on created_time/last_edited_time
        if flt is None:
            return pages_rows
        if not isinstance(flt, dict):
            return None  # malformed
        if "and" in flt:
            arr = flt.get("and")
            if not isinstance(arr, list):
                return None
            out = pages_rows
            for sub in arr:
                out = _apply_filter(out, sub)
                if out is None:
                    return None
            return out
        if "or" in flt:
            arr = flt.get("or")
            if not isinstance(arr, list):
                return None
            union = []
            seen = set()
            for sub in arr:
                part = _apply_filter(pages_rows, sub)
                if part is None:
                    return None
                for r in part:
                    rid = r.get("id")
                    if rid not in seen:
                        seen.add(rid)
                        union.append(r)
            return union

        # property filter
        prop = flt.get("property")
        if not isinstance(prop, str) or prop == "":
            return None
        # created_time / last_edited_time special cases
        if prop in ("created_time", "last_edited_time"):
            tfilter = flt.get("timestamp")
            if not isinstance(tfilter, str) or tfilter not in ("created_time", "last_edited_time"):
                # accept without timestamp key, infer
                tfilter = prop
            cond = flt.get(tfilter) if isinstance(flt.get(tfilter), dict) else None
            if not isinstance(cond, dict):
                return None
            # support on_or_after / on_or_before
            after = cond.get("on_or_after")
            before = cond.get("on_or_before")
            if after is not None and not isinstance(after, str):
                return None
            if before is not None and not isinstance(before, str):
                return None
            adt = _parse_dt(after) if after else None
            bdt = _parse_dt(before) if before else None

            def _ts(page):
                return _parse_dt(page.get("created_at" if tfilter == "created_time" else "updated_at")) or datetime.datetime.min

            out = []
            for r in pages_rows:
                ts = _ts(r)
                if adt and ts < adt:
                    continue
                if bdt and ts > bdt:
                    continue
                out.append(r)
            return out

        # equals / contains
        # Notion-style: {property:"Name", rich_text:{contains:"x"}} etc. We'll accept {equals:...} directly too.
        def _cond_from_dict(d):
            for k in ("equals", "contains", "does_not_equal"):
                if k in d:
                    return k, d.get(k)
            return None, None

        cond_obj = None
        for k in ("rich_text", "title", "select", "status", "number", "checkbox", "date"):
            if isinstance(flt.get(k), dict):
                cond_obj = flt.get(k)
                break
        if cond_obj is None and isinstance(flt.get("equals"), (str, int, float, bool)) or "contains" in flt:
            cond_obj = flt

        if not isinstance(cond_obj, dict):
            return None

        op, val = _cond_from_dict(cond_obj)
        if op is None:
            return None

        out = []
        for r in pages_rows:
            pv = _get_prop_value(r, prop)
            sv = _extract_sortable(pv)
            if op == "equals":
                if sv == val:
                    out.append(r)
            elif op == "does_not_equal":
                if sv != val:
                    out.append(r)
            elif op == "contains":
                if isinstance(sv, str) and isinstance(val, str) and val.casefold() in sv.casefold():
                    out.append(r)
        return out

    t0 = time.time()
    endpoint = "query-database"

    db_pat = re.compile(r"^ntn_db_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(database_id, str) or not db_pat.match(database_id):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
        return _err("VALIDATION_ERROR", "database_id is invalid.")

    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 100):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if page_size is None:
        page_size = 100
    if start_cursor is not None and not isinstance(start_cursor, str):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
        return _err("VALIDATION_ERROR", "start_cursor must be a string.")

    if filter is not None and not isinstance(filter, dict):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
        return _err("VALIDATION_ERROR", "filter must be an object.")
    if sorts is not None:
        if not isinstance(sorts, list):
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
            return _err("VALIDATION_ERROR", "sorts must be an array.")
        for s in sorts:
            if not isinstance(s, dict):
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
                return _err("VALIDATION_ERROR", "Each sort must be an object.")
            if "property" not in s or "direction" not in s:
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
                return _err("VALIDATION_ERROR", "Each sort must include property and direction.")
            if not isinstance(s.get("property"), str) or s["property"] == "":
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
                return _err("VALIDATION_ERROR", "Sort property must be a non-empty string.")
            if s.get("direction") not in ("ascending", "descending"):
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=None)
                return _err("VALIDATION_ERROR", "Sort direction must be ascending or descending.")

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []
    db = None
    for d in dbs:
        if isinstance(d, dict) and d.get("id") == database_id:
            db = d
            break
    if db is None:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "NOT_FOUND", latency, workspace_id_used=None)
        return _err("NOT_FOUND", "Database not found.")
    workspace_id_used = db.get("workspace_id")

    # Ambient auth: must have some accessible workspace context; if missing, unauthorized.
    if not isinstance(workspace_id_used, str) or workspace_id_used == "":
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "UNAUTHORIZED", latency, workspace_id_used=None)
        return _err("UNAUTHORIZED", "Workspace context unavailable.")

    limerr = _enforce_limits(endpoint, workspace_id_used)
    if limerr:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, limerr["error"]["code"], latency, workspace_id_used=workspace_id_used)
        return limerr

    # Validate sorts against schema if provided (properties must exist in properties_schema or be created_time/last_edited_time)
    schema = db.get("properties_schema")
    if not isinstance(schema, dict):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=workspace_id_used)
        return _err("VALIDATION_ERROR", "Database properties_schema is invalid.")
    if sorts:
        for s in sorts:
            prop = s.get("property")
            if prop in ("created_time", "last_edited_time"):
                continue
            if prop not in schema:
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=workspace_id_used)
                return _err("VALIDATION_ERROR", f"Unknown sort property: {prop}")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    rows = []
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") != workspace_id_used:
            continue
        if p.get("parent_type") != "database":
            continue
        if p.get("parent_database_id") != database_id:
            continue
        if p.get("status") == "deleted":
            continue
        # typical: exclude archived pages unless API requests otherwise; no parameter here, so exclude
        if p.get("status") == "archived" or p.get("archived") is True:
            continue
        rows.append(p)

    # Apply filter
    if filter is not None:
        filtered = _apply_filter(rows, filter)
        if filtered is None:
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=workspace_id_used)
            return _err("VALIDATION_ERROR", "filter payload is malformed or unsupported.")
        rows = filtered

    # Sorting: stable ordering with fallback (updated_at, id)
    effective_sorts = sorts if sorts else [{"property": "last_edited_time", "direction": "descending"}]

    def _sort_key(p):
        keys = []
        for s in effective_sorts:
            prop = s["property"]
            if prop == "created_time":
                dt = _parse_dt(p.get("created_at")) or datetime.datetime.min
                keys.append(dt)
            elif prop == "last_edited_time":
                dt = _parse_dt(p.get("updated_at")) or datetime.datetime.min
                keys.append(dt)
            else:
                keys.append(_extract_sortable(_get_prop_value(p, prop)))
        # stable tie-break
        dt2 = _parse_dt(p.get("updated_at")) or datetime.datetime.min
        keys.append(dt2)
        keys.append(str(p.get("id", "")))
        return tuple(keys)

    # Apply per-sort direction by transforming keys
    directions = [s["direction"] for s in effective_sorts] + ["descending", "ascending"]

    def _normalize_for_compare(v):
        if v is None:
            return (1, "")
        if isinstance(v, bool):
            return (0, int(v))
        if isinstance(v, (int, float)):
            return (0, v)
        if isinstance(v, datetime.datetime):
            return (0, v.timestamp())
        return (0, str(v).casefold())

    def _cmp_tuple(p):
        raw = _sort_key(p)
        out = []
        for i, v in enumerate(raw):
            norm = _normalize_for_compare(v)
            # invert for descending where possible
            dirn = directions[i] if i < len(directions) else "ascending"
            if dirn == "descending":
                out.append((norm[0], norm[1], 1))  # mark desc; we'll sort with custom transform
            else:
                out.append((norm[0], norm[1], 0))
        return tuple(out)

    # Convert into composite key that respects direction without custom comparator
    # For descending fields, invert numeric/time; for strings, invert by using reversed ordering via tuple flag.
    def _final_key(p):
        raw = _sort_key(p)
        final = []
        for i, v in enumerate(raw):
            dirn = directions[i] if i < len(directions) else "ascending"
            if isinstance(v, datetime.datetime):
                n = v.timestamp()
                final.append(-n if dirn == "descending" else n)
            elif isinstance(v, (int, float)):
                final.append(-v if dirn == "descending" else v)
            elif isinstance(v, bool):
                n = int(v)
                final.append(-n if dirn == "descending" else n)
            else:
                s = "" if v is None else str(v).casefold()
                # For descending strings, we can't invert easily; use (flag, value) with flag reversed later
                final.append((0, s) if dirn == "ascending" else (1, s))
        return tuple(final)

    rows.sort(key=_final_key)

    # Cursor: base64 json {"k":[...]} where k is updated_at iso + id (stable cursor)
    def _encode_cursor(p):
        dt = _parse_dt(p.get("updated_at")) or datetime.datetime.min
        payload = {"k": [dt.isoformat(), str(p.get("id", ""))]}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "k" not in obj or not isinstance(obj["k"], list) or len(obj["k"]) != 2:
                return None
            dt = _parse_dt(obj["k"][0]) or datetime.datetime.min
            pid = str(obj["k"][1])
            return (dt, pid)
        except Exception:
            return None

    start_idx = 0
    if start_cursor:
        ck = _decode_cursor(start_cursor)
        if ck is None:
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "VALIDATION_ERROR", latency, workspace_id_used=workspace_id_used)
            return _err("VALIDATION_ERROR", "start_cursor is invalid.")
        # Find first item strictly after cursor by (updated_at,id) in the current sorted order.
        # Use the stable key for cursor scan.
        for i, p in enumerate(rows):
            dt = _parse_dt(p.get("updated_at")) or datetime.datetime.min
            pid = str(p.get("id", ""))
            if (dt, pid) > ck:
                start_idx = i
                break
        else:
            start_idx = len(rows)

    page_rows = rows[start_idx:start_idx + page_size]
    has_more = (start_idx + page_size) < len(rows)
    next_cursor = _encode_cursor(page_rows[-1]) if has_more and page_rows else None

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, "OK", latency, workspace_id_used=workspace_id_used)

    return {
        "object": "list",
        "results": page_rows,
        "database_id": database_id,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "page_size": page_size,
    }

def create_database(parent_page_id, title, description=None, properties_schema=None, icon=None, cover=None, is_inline=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "create-database",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        # writes a bit stricter
        if cnt >= 60:
            return False, {"limit": 60, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    def _new_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    pg_pat = re.compile(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(parent_page_id, str) or not pg_pat.match(parent_page_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "parent_page_id"})
        return _err("VALIDATION_ERROR", "parent_page_id is malformed.", field="parent_page_id")
    if not isinstance(title, str) or not title.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "title"})
        return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")
    if properties_schema is None or not isinstance(properties_schema, dict):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "properties_schema"})
        return _err("VALIDATION_ERROR", "properties_schema must be a JSON object.", field="properties_schema")
    if description is not None and not isinstance(description, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if icon is not None and not isinstance(icon, dict):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "icon"})
        return _err("VALIDATION_ERROR", "icon must be an object.", field="icon")
    if cover is not None and not isinstance(cover, dict):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "cover"})
        return _err("VALIDATION_ERROR", "cover must be an object.", field="cover")
    if is_inline is None:
        is_inline = False
    if not isinstance(is_inline, bool):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "is_inline"})
        return _err("VALIDATION_ERROR", "is_inline must be boolean.", field="is_inline")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    parent_page = next((p for p in pages if isinstance(p, dict) and p.get("id") == parent_page_id), None)
    if not parent_page or parent_page.get("status") in ("deleted",) or parent_page.get("archived") is True:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Parent page not found or not active.")

    workspace_id = parent_page.get("workspace_id")
    if not workspace_id:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No accessible workspace context.")

    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    # Ensure schema has at least a title property; if missing, initialize (accept empty schema from caller)
    if "title" not in properties_schema:
        properties_schema = dict(properties_schema)
        properties_schema["title"] = {"type": "title"}

    databases = _load("databases.json")
    if not isinstance(databases, list):
        databases = []

    # Create ID and ensure uniqueness
    existing_ids = {d.get("id") for d in databases if isinstance(d, dict)}
    new_id = _new_id("ntn_db_")
    while new_id in existing_ids:
        new_id = _new_id("ntn_db_")

    now = _now()
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "parent_page_id": parent_page_id,
        "title": title.strip(),
        "description": description,
        "properties_schema": properties_schema,
        "icon": icon,
        "cover": cover,
        "is_inline": bool(is_inline),
        "archived": False,
        "status": "active",
        "created_by_user_id": None,
        "last_edited_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }
    databases.append(row)
    _save("databases.json", databases)

    # Upsert search index row
    sidx = _load("search_index.json")
    if not isinstance(sidx, list):
        sidx = []
    # uniqueness: (workspace_id, object_type, page_id, database_id)
    existing = None
    for r in sidx:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == workspace_id and r.get("object_type") == "database" and r.get("database_id") == new_id:
            existing = r
            break
    if existing is None:
        srow = {
            "id": _new_id("ntn_sidx_"),
            "workspace_id": workspace_id,
            "object_type": "database",
            "page_id": None,
            "database_id": new_id,
            "title_text": title.strip(),
            "content_text": None,
            "token_vector": None,
            "last_indexed_at": now,
            "status": "ready",
            "created_at": now,
            "updated_at": now,
        }
        sidx.append(srow)
    else:
        existing["database_id"] = new_id
        existing["page_id"] = None
        existing["object_type"] = "database"
        existing["title_text"] = title.strip()
        existing["status"] = "stale"
        existing["updated_at"] = now
    _save("search_index.json", sidx)

    _log("ok", workspace=workspace_id, meta={"database_id": new_id})
    return row

def update_database(database_id, title=None, description=None, properties_schema=None, icon=None, cover=None, archived=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_str, workspace=None, meta=None, error_code=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "update-database",
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        if not workspace:
            return True, None
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            dt = _parse_dt(r.get("timestamp") or r.get("ts"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=60, workspace_id=workspace)
        return True, None

    try:
        if not isinstance(database_id, str) or not re.match(r"^ntn_db_[0-9A-HJKMNP-TV-Z]{10,}$", database_id):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "database_id"})
            return _err("VALIDATION_ERROR", "database_id is malformed", field="database_id")

        # ensure at least one updatable field provided
        provided = {
            "title": title, "description": description, "properties_schema": properties_schema,
            "icon": icon, "cover": cover, "archived": archived, "status": status
        }
        if all(v is None for v in provided.values()):
            _log("error", None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "No updatable fields provided")

        if title is not None and (not isinstance(title, str) or title.strip() == ""):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "title"})
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
        if description is not None and not (isinstance(description, str) or description is None):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "description"})
            return _err("VALIDATION_ERROR", "description must be a string", field="description")
        if properties_schema is not None and not isinstance(properties_schema, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "properties_schema"})
            return _err("VALIDATION_ERROR", "properties_schema must be a valid JSON object", field="properties_schema", rule="properties_schema must be valid JSON object")
        if icon is not None and not isinstance(icon, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "icon"})
            return _err("VALIDATION_ERROR", "icon must be a JSON object", field="icon")
        if cover is not None and not isinstance(cover, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "cover"})
            return _err("VALIDATION_ERROR", "cover must be a JSON object", field="cover")
        if archived is not None and not isinstance(archived, bool):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "archived"})
            return _err("VALIDATION_ERROR", "archived must be a boolean", field="archived")
        if status is not None and status not in ("active", "archived"):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived", field="status")

        dbs = _load("databases.json")
        if not isinstance(dbs, list):
            dbs = []
        pages = _load("pages.json")
        if not isinstance(pages, list):
            pages = []
        sidx = _load("search_index.json")
        if not isinstance(sidx, list):
            sidx = []

        db = None
        for r in dbs:
            if isinstance(r, dict) and r.get("id") == database_id:
                db = r
                break
        if not db:
            _log("error", None, error_code="NOT_FOUND", meta={"database_id": database_id})
            return _err("NOT_FOUND", "Database not found", database_id=database_id)

        workspace_id = db.get("workspace_id")
        ok, rlerr = _rate_limit_check(workspace_id)
        if not ok:
            _log("error", workspace_id, error_code=rlerr["error"]["code"])
            return rlerr

        # lifecycle/archived-status handling: accept either archived or status or both.
        # If both are provided and inconsistent => validation error.
        if archived is not None and status is not None:
            if archived != (status == "archived"):
                _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "archived", "rule": "archived = (status = 'archived')"})
                return _err("VALIDATION_ERROR", "archived must equal (status == 'archived')", rule="archived = (status = 'archived')", field="archived")
        # if only one is provided, derive the other to enforce invariant
        new_status = status if status is not None else ("archived" if archived is True else ("active" if archived is False else None))
        new_archived = archived if archived is not None else (True if status == "archived" else (False if status == "active" else None))

        # Apply lifecycle transition if status changes
        if new_status is not None and new_status != db.get("status"):
            cur = db.get("status")
            allowed = {"active": ["archived"], "archived": ["active"]}
            if cur not in allowed or new_status not in allowed[cur]:
                _log("error", workspace_id, error_code="INVALID_TRANSITION", meta={"from": cur, "to": new_status})
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {new_status}", from_status=cur, to_status=new_status)

        # validate schema update against existing database pages
        if properties_schema is not None:
            # must include at least one title-like property
            has_title = False
            for k, v in properties_schema.items():
                if isinstance(v, dict) and v.get("type") == "title":
                    has_title = True
                    break
            if not has_title:
                _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "properties_schema"})
                return _err("VALIDATION_ERROR", "properties_schema must include at least one property with type='title'", field="properties_schema")

            # Reject if existing pages contain properties not present in new schema or missing required title prop
            db_page_rows = [p for p in pages if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("parent_type") == "database" and p.get("parent_database_id") == database_id and p.get("status") != "deleted"]
            for p in db_page_rows:
                props = p.get("properties")
                if not isinstance(props, dict):
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"page_id": p.get("id")})
                    return _err("VALIDATION_ERROR", "Existing page has invalid properties object; cannot migrate", page_id=p.get("id"))
                # ensure all keys present are allowed by new schema
                for prop_name in props.keys():
                    if prop_name not in properties_schema:
                        _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"page_id": p.get("id"), "property": prop_name})
                        return _err("VALIDATION_ERROR", "properties_schema update is incompatible with existing pages (unknown property)", rule="update-database schema compatibility", page_id=p.get("id"), property=prop_name)
                # ensure title property exists in page properties (Notion requires title)
                # find the title property name(s)
                title_names = [k for k, v in properties_schema.items() if isinstance(v, dict) and v.get("type") == "title"]
                if title_names and not any(n in props for n in title_names):
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"page_id": p.get("id")})
                    return _err("VALIDATION_ERROR", "properties_schema update would invalidate existing pages (missing title property)", rule="update-database schema compatibility", page_id=p.get("id"))

        # perform update (no success without effect)
        before = json.dumps(db, sort_keys=True, default=str)
        if title is not None:
            db["title"] = title
        if description is not None:
            db["description"] = description
        if icon is not None:
            db["icon"] = icon
        if cover is not None:
            db["cover"] = cover
        if properties_schema is not None:
            db["properties_schema"] = properties_schema
        if new_status is not None:
            db["status"] = new_status
        if new_archived is not None:
            db["archived"] = new_archived

        db["updated_at"] = _now()
        # last_edited_by_user_id is not resolvable without auth context; keep existing if present.

        after = json.dumps(db, sort_keys=True, default=str)
        if after == before:
            _log("error", workspace_id, error_code="CONFLICT")
            return _err("CONFLICT", "Update made no changes")

        _save("databases.json", dbs)

        # upsert search index row and mark stale/ready? For metadata change, mark stale.
        # Find matching index row
        idx = None
        for r in sidx:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("object_type") == "database" and r.get("database_id") == database_id:
                idx = r
                break
        now = _now()
        if idx is None:
            # create row id
            rid = f"ntn_sidx_{int(time.time()*1000)}_{os.getpid()}_{len(sidx)+1}"
            idx = {
                "id": rid,
                "workspace_id": workspace_id,
                "object_type": "database",
                "page_id": None,
                "database_id": database_id,
                "title_text": (db.get("title") or "").strip() or None,
                "content_text": None,
                "token_vector": None,
                "last_indexed_at": now,
                "status": "stale",
                "created_at": now,
                "updated_at": now,
            }
            sidx.append(idx)
        else:
            idx["title_text"] = (db.get("title") or "").strip() or idx.get("title_text")
            # metadata change => stale
            cur = idx.get("status")
            if cur in ("ready", "stale", "disabled"):
                if cur != "disabled":
                    idx["status"] = "stale"
            idx["updated_at"] = now
        _save("search_index.json", sidx)

        _log("ok", workspace_id, meta={"database_id": database_id})
        return {"object": "database", "database": db}
    except Exception as e:
        _log("error", None, error_code="VALIDATION_ERROR", meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def get_page(page_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")
    def _load(n):
