    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_page"
    requests_file = "request_log.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, workspace_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{int(latency_ms)}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "workspace_id": workspace_id
        }
        if error_code:
            row["error_code"] = error_code
        logs = _load(requests_file)
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(requests_file, logs)

    # Validation
    if not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", page_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is malformed", field="page_id")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []

    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id), None)
    if not page:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Page not found", page_id=page_id)

    # Conflict if deleted
    if page.get("status") == "deleted":
        _log("error", workspace_id=page.get("workspace_id"), error_code="CONFLICT")
        return _err("CONFLICT", "Page is deleted and cannot be retrieved", page_id=page_id)

    # Ambient auth: pick a workspace that matches the page. If page has workspace_id, it is accessible.
    wsid = page.get("workspace_id")
    if not isinstance(wsid, str) or not wsid:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible workspace context for this page")

    # Return metadata/properties only (no blocks)
    result = {
        "object": "page",
