    }

    _log("ok", workspace_id=wsid)
    return {"data": result}

def create_page(parent_type, title, parent_page_id=None, parent_database_id=None, properties=None, icon=None, cover=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_str, workspace=None, meta=None, error_code=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "create-page",
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        if not workspace:
            return True, None
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            dt = _parse_dt(r.get("timestamp") or r.get("ts"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, {"limit": 60, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    # Validate inputs
    if parent_type not in ("page", "database"):
        _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "parent_type"})
        return _err("VALIDATION_ERROR", "parent_type must be one of: page, database", field="parent_type")

    if not isinstance(title, str) or title.strip() == "":
        _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")

    if properties is not None and not isinstance(properties, dict):
        _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "properties"})
        return _err("VALIDATION_ERROR", "properties must be a JSON object", field="properties")

    if icon is not None and not isinstance(icon, dict):
        _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "icon"})
        return _err("VALIDATION_ERROR", "icon must be a JSON object", field="icon")

    if cover is not None and not isinstance(cover, dict):
        _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "cover"})
        return _err("VALIDATION_ERROR", "cover must be a JSON object", field="cover")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    workspace_id = None
    if parent_type == "page":
        if not isinstance(parent_page_id, str) or not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", parent_page_id):
            _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "parent_page_id"})
            return _err("VALIDATION_ERROR", "parent_page_id is required and must be a valid page id", field="parent_page_id")
        # parent_database_id must be null/unused
        parent = None
        for p in pages:
            if isinstance(p, dict) and p.get("id") == parent_page_id:
                parent = p
                break
        if not parent or parent.get("status") != "active":
            _log("error", workspace=None, error_code="NOT_FOUND", meta={"parent_page_id": parent_page_id})
            return _err("NOT_FOUND", "Parent page not found", parent_page_id=parent_page_id)
        workspace_id = parent.get("workspace_id")
    else:
        if not isinstance(parent_database_id, str) or not re.match(r"^ntn_db_[0-9A-HJKMNP-TV-Z]{10,}$", parent_database_id):
            _log("error", workspace=None, error_code="VALIDATION_ERROR", meta={"field": "parent_database_id"})
            return _err("VALIDATION_ERROR", "parent_database_id is required and must be a valid database id", field="parent_database_id")
        db = None
        for d in dbs:
            if isinstance(d, dict) and d.get("id") == parent_database_id:
                db = d
                break
        if not db or db.get("status") != "active":
            _log("error", workspace=None, error_code="NOT_FOUND", meta={"parent_database_id": parent_database_id})
            return _err("NOT_FOUND", "Parent database not found", parent_database_id=parent_database_id)
        workspace_id = db.get("workspace_id")

        # validate properties against schema
        schema = db.get("properties_schema")
        if not isinstance(schema, dict):
            _log("error", workspace=workspace_id, error_code="CONFLICT", meta={"rule": "database schema missing/invalid"})
            return _err("CONFLICT", "Database schema is invalid; cannot create page", rule="properties_schema must be valid JSON object")

        props = properties or {}
        # require that provided keys exist in schema
        unknown = sorted([k for k in props.keys() if k not in schema])
        if unknown:
            _log("error", workspace=workspace_id, error_code="VALIDATION_ERROR", meta={"unknown_properties": unknown})
            return _err("VALIDATION_ERROR", "properties contain keys not present in database schema", unknown_properties=unknown)

    ok, info = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, error_code="RATE_LIMIT", meta=info)
        return _err("RATE_LIMIT", "Rate limit exceeded", **info)

    # Generate id
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    existing_ids = {p.get("id") for p in pages if isinstance(p, dict)}
    new_id = _gen_id("ntn_pg_")
    tries = 0
    while new_id in existing_ids and tries < 10:
        new_id = _gen_id("ntn_pg_")
        tries += 1
    if new_id in existing_ids:
        _log("error", workspace=workspace_id, error_code="CONFLICT", meta={"rule": "id collision"})
        return _err("CONFLICT", "Could not allocate a unique page id", rule="unique(workspace_id, id)")

    now = _now()
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "parent_type": parent_type,
        "parent_page_id": parent_page_id if parent_type == "page" else None,
        "parent_database_id": parent_database_id if parent_type == "database" else None,
        "title": title,
        "properties": properties or {},
        "icon": icon,
        "cover": cover,
        "archived": False,
        "status": "active",
        "created_by_user_id": None,
        "last_edited_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }

    # enforce "exactly one of parent_page_id, parent_database_id"
    if parent_type == "page":
        if row["parent_page_id"] is None or row["parent_database_id"] is not None:
            _log("error", workspace=workspace_id, error_code="VALIDATION_ERROR", meta={"rule": "exactly one of parent_page_id, parent_database_id must be non-null"})
            return _err("VALIDATION_ERROR", "Exactly one parent id must be set for the given parent_type", rule="exactly one of parent_page_id, parent_database_id must be non-null and must match parent_type")
    else:
        if row["parent_database_id"] is None or row["parent_page_id"] is not None:
            _log("error", workspace=workspace_id, error_code="VALIDATION_ERROR", meta={"rule": "exactly one of parent_page_id, parent_database_id must be non-null"})
            return _err("VALIDATION_ERROR", "Exactly one parent id must be set for the given parent_type", rule="exactly one of parent_page_id, parent_database_id must be non-null and must match parent_type")

    pages.append(row)
    _save("pages.json", pages)

    # Ensure search_index row exists (stale) for this page
    sidx = _load("search_index.json")
    if not isinstance(sidx, list):
        sidx = []
    new_si_id = f"ntn_sidx_{int(time.time()*1000)}_{os.getpid()}_{len(sidx)+1}"
    sidx.append({
        "id": new_si_id,
        "workspace_id": workspace_id,
        "object_type": "page",
        "page_id": new_id,
        "database_id": None,
        "title_text": title,
        "content_text": None,
        "token_vector": None,
        "last_indexed_at": now,
        "status": "stale",
        "created_at": now,
        "updated_at": now,
    })
    _save("search_index.json", sidx)

    _log("ok", workspace=workspace_id, meta={"page_id": new_id})
    return {"object": "page", "page": row}

def update_page(page_id, properties=None, title=None, icon=None, cover=None, archived=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status_s, workspace=None, meta=None, error_code=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "update-page",
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            dt = _parse_dt(r.get("timestamp") or r.get("ts"))
            if dt and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, {"limit": 60, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    # Validation
    if not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", page_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is malformed", field="page_id")

    if properties is None and title is None and icon is None and cover is None and archived is None and status is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    if properties is not None and not isinstance(properties, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object", field="properties")
    if title is not None and (not isinstance(title, str) or title.strip() == ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string when provided", field="title")
    if icon is not None and not isinstance(icon, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "icon must be an object", field="icon")
    if cover is not None and not isinstance(cover, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cover must be an object", field="cover")
    if archived is not None and not isinstance(archived, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be boolean", field="archived")
    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []
    sidx = _load("search_index.json")
    if not isinstance(sidx, list):
        sidx = []

    page = None
    for p in pages:
        if isinstance(p, dict) and p.get("id") == page_id:
            page = p
            break
    if not page:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Page not found", page_id=page_id)

    workspace_id = page.get("workspace_id")
    ok, info = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, error_code="RATE_LIMIT", meta=info)
        return _err("RATE_LIMIT", "Rate limit exceeded", **(info or {}))

    # Normalize desired status/archived
    desired_status = status if status is not None else page.get("status")
    desired_archived = archived if archived is not None else page.get("archived")
    if status is not None and archived is None:
        desired_archived = (status == "archived")
    if archived is not None and status is None:
        desired_status = "archived" if archived else "active"
    if status is not None and archived is not None and (archived != (status == "archived")):
        desired_archived = (status == "archived")

    # Lifecycle transition only if status changes
    current_status = page.get("status")
    if desired_status != current_status:
        transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        allowed = transitions.get(current_status, [])
        if desired_status not in allowed:
            _log("error", workspace=workspace_id, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=current_status, to_status=desired_status)
    else:
        # Do not raise INVALID_TRANSITION when no-op
        pass

    # If page belongs to database, validate property updates keys against schema
    if properties is not None and page.get("parent_type") == "database":
        dbid = page.get("parent_database_id")
        db = None
        for d in dbs:
            if isinstance(d, dict) and d.get("id") == dbid and d.get("workspace_id") == workspace_id:
                db = d
                break
        if not db:
            _log("error", workspace=workspace_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Parent database not found for page", parent_database_id=dbid)
        schema = db.get("properties_schema")
        if not isinstance(schema, dict):
            _log("error", workspace=workspace_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Database schema is invalid", database_id=dbid)
        unknown = [k for k in properties.keys() if k not in schema]
        if unknown:
            _log("error", workspace=workspace_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties contain keys not present in database schema", unknown_properties=unknown)

    changed = False
    if title is not None and title != page.get("title"):
        page["title"] = title
        changed = True
    if icon is not None:
        if icon != page.get("icon"):
            page["icon"] = icon
            changed = True
    if cover is not None:
        if cover != page.get("cover"):
            page["cover"] = cover
            changed = True
    if properties is not None:
        # merge semantics: replace provided keys, keep others
        existing = page.get("properties")
        if not isinstance(existing, dict):
            existing = {}
        merged = dict(existing)
        merged.update(properties)
        if merged != existing:
            page["properties"] = merged
            changed = True

    if desired_status != page.get("status"):
        page["status"] = desired_status
        changed = True
    if desired_archived != page.get("archived"):
        page["archived"] = desired_archived
        changed = True

    if not changed:
        _log("error", workspace=workspace_id, error_code="CONFLICT")
        return _err("CONFLICT", "No changes to apply")

    page["updated_at"] = _now()

    # Mark page search index as stale
    idx_row = None
    for r in sidx:
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("object_type") == "page" and r.get("page_id") == page_id:
            idx_row = r
            break
    if idx_row is None:
        # create if missing
        now = _now()
        sidx.append({
            "id": f"ntn_sidx_{int(time.time()*1000)}_{os.getpid()}_{len(sidx)+1}",
            "workspace_id": workspace_id,
            "object_type": "page",
            "page_id": page_id,
            "database_id": None,
            "title_text": page.get("title"),
            "content_text": None,
            "token_vector": None,
            "last_indexed_at": now,
            "status": "stale",
            "created_at": now,
            "updated_at": now,
        })
    else:
        idx_row["title_text"] = page.get("title")
        idx_row["status"] = "stale"
        idx_row["updated_at"] = _now()

    _save("pages.json", pages)
    _save("search_index.json", sidx)

    _log("ok", workspace=workspace_id)
    return {"object": "page", "page": page}

