def get_block_children(block_id, page_size=None, start_cursor=None, include_archived=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "get-block-children",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    if not isinstance(block_id, str) or not re.match(r"^ntn_blk_[0-9A-Z]{4,}$", block_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "block_id"})
        return _err("VALIDATION_ERROR", "block_id is malformed.", field="block_id")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")

    if include_archived is None:
        include_archived = False
    if not isinstance(include_archived, bool):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "include_archived"})
        return _err("VALIDATION_ERROR", "include_archived must be boolean.", field="include_archived")

    blocks = _load("blocks.json")
    if not isinstance(blocks, list):
        blocks = []
    parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id), None)
    if not parent:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Parent block not found.")

    workspace_id = parent.get("workspace_id")
    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    # Cursor semantics: "v1:<sort_index>:<id>"
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
        return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")

    children = []
    for b in blocks:
        if not isinstance(b, dict):
            continue
        if b.get("page_id") != parent.get("page_id"):
            continue
        if b.get("parent_block_id") != block_id:
            continue
        if not include_archived and b.get("status") != "active":
            continue
        children.append(b)

    children.sort(key=lambda r: (float(r.get("sort_index") or 0.0), r.get("id") or ""))

    start_idx = 0
    if start_cursor:
        if not start_cursor.startswith("v1:"):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        parts = start_cursor.split(":", 2)
        if len(parts) != 3:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        _, s_si, s_id = parts
        try:
            s_si_f = float(s_si)
        except Exception:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")

        for i, r in enumerate(children):
            try:
                r_si = float(r.get("sort_index") or 0.0)
            except Exception:
                r_si = 0.0
            if (r_si, r.get("id") or "") > (s_si_f, s_id):
                start_idx = i
                break
        else:
            start_idx = len(children)

    page = children[start_idx:start_idx + page_size]
    has_more = (start_idx + page_size) < len(children)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        try:
            si = float(last.get("sort_index") or 0.0)
        except Exception:
            si = 0.0
        next_cursor = f"v1:{si}:{last.get('id') or ''}"

    resp = {"results": page, "has_more": has_more, "next_cursor": next_cursor, "total": len(children)}
    _log("ok", workspace=workspace_id, meta={"returned": len(page), "total": len(children)})
    return resp

def append_block_children(block_id, children, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "append-block-children",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, {"limit": 60, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    def _new_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").upper()

    allowed_types = {
        "paragraph", "heading_1", "heading_2", "heading_3",
        "bulleted_list_item", "numbered_list_item", "to_do", "toggle",
        "quote", "code", "callout", "divider", "image", "file", "bookmark",
        "table", "table_row", "child_page", "child_database", "synced_block", "unsupported"
    }

    def _validate_block_payload(btype, data_obj):
        if data_obj is None:
            return True, None
        if not isinstance(data_obj, dict):
            return False, "data must be an object"
        # type-specific invariants (minimal)
        if btype == "to_do":
            if "checked" in data_obj and not isinstance(data_obj.get("checked"), bool):
                return False, "to_do.checked must be boolean"
        if btype == "code":
            if "language" in data_obj and not isinstance(data_obj.get("language"), str):
                return False, "code.language must be string"
        return True, None

    if not isinstance(block_id, str) or not re.match(r"^ntn_blk_[0-9A-Z]{4,}$", block_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "block_id"})
        return _err("VALIDATION_ERROR", "block_id is malformed.", field="block_id")
    if not isinstance(children, list) or len(children) < 1:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "children"})
        return _err("VALIDATION_ERROR", "children must be a non-empty array.", field="children")

    blocks = _load("blocks.json")
    if not isinstance(blocks, list):
        blocks = []
    parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id), None)
    if not parent:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Parent block not found.")
    if parent.get("status") == "deleted":
        _log("error", workspace=parent.get("workspace_id"), meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Cannot append children to a deleted block.")

    workspace_id = parent.get("workspace_id")
    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    # Validate all children first
    for idx, ch in enumerate(children):
        if not isinstance(ch, dict):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}]"})
            return _err("VALIDATION_ERROR", "Each child must be an object.", field=f"children[{idx}]")
        btype = ch.get("type")
        if not isinstance(btype, str) or btype not in allowed_types:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}].type"})
            return _err("VALIDATION_ERROR", "A child block is missing type or type is invalid.", field=f"children[{idx}].type")
        okp, msg = _validate_block_payload(btype, ch.get("data", {}))
        if not okp:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}].data"})
            return _err("VALIDATION_ERROR", msg, field=f"children[{idx}].data")
        if "children" in ch and ch["children"] is not None:
            if not isinstance(ch["children"], list):
                _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}].children"})
                return _err("VALIDATION_ERROR", "children[].children must be an array.", field=f"children[{idx}].children")
            for j, nch in enumerate(ch["children"]):
                if not isinstance(nch, dict) or not isinstance(nch.get("type"), str) or nch.get("type") not in allowed_types:
                    _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}].children[{j}].type"})
                    return _err("VALIDATION_ERROR", "Nested child block type is missing or invalid.", field=f"children[{idx}].children[{j}].type")
                okp2, msg2 = _validate_block_payload(nch.get("type"), nch.get("data", {}))
                if not okp2:
                    _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": f"children[{idx}].children[{j}].data"})
                    return _err("VALIDATION_ERROR", msg2, field=f"children[{idx}].children[{j}].data")

    # Compute sort_index allocation
    siblings = [b for b in blocks if isinstance(b, dict) and b.get("page_id") == parent.get("page_id") and b.get("parent_block_id") == block_id]
    max_si = 0.0
    for s in siblings:
        try:
            max_si = max(max_si, float(s.get("sort_index") or 0.0))
        except Exception:
            continue

    now = _now()
    existing_ids = {b.get("id") for b in blocks if isinstance(b, dict)}
    created = []

    def _append_one(ch, parent_block_id):
        nonlocal max_si, blocks, existing_ids, created
        bid = _new_id("ntn_blk_")
        while bid in existing_ids:
            bid = _new_id("ntn_blk_")
        existing_ids.add(bid)
        max_si = max_si + 1.0
        btype = ch.get("type")
        data_obj = ch.get("data", {})
        if data_obj is None:
            data_obj = {}
        row = {
            "id": bid,
            "workspace_id": workspace_id,
            "page_id": parent.get("page_id"),
            "parent_block_id": parent_block_id,
            "type": btype,
            "data": data_obj if isinstance(data_obj, dict) else {},
            "has_children": bool(ch.get("children")) if isinstance(ch.get("children"), list) and len(ch.get("children")) > 0 else False,
            "sort_index": max_si,
            "archived": False,
            "status": "active",
            "created_by_user_id": None,
            "last_edited_by_user_id": None,
            "created_at": now,
            "updated_at": now,
        }
        blocks.append(row)
        created.append(row)
        # nested children
        if isinstance(ch.get("children"), list) and ch["children"]:
            # nested children start at 0 for this new parent
            nested_max = 0.0
            for nch in ch["children"]:
                nbid = _new_id("ntn_blk_")
                while nbid in existing_ids:
                    nbid = _new_id("ntn_blk_")
                existing_ids.add(nbid)
                nested_max += 1.0
                ntype = nch.get("type")
                ndata = nch.get("data", {})
                if ndata is None:
                    ndata = {}
                nrow = {
                    "id": nbid,
                    "workspace_id": workspace_id,
                    "page_id": parent.get("page_id"),
                    "parent_block_id": bid,
                    "type": ntype,
                    "data": ndata if isinstance(ndata, dict) else {},
                    "has_children": False,
                    "sort_index": nested_max,
                    "archived": False,
                    "status": "active",
                    "created_by_user_id": None,
                    "last_edited_by_user_id": None,
                    "created_at": now,
                    "updated_at": now,
                }
                blocks.append(nrow)
                created.append(nrow)
            row["has_children"] = True

    for ch in children:
        _append_one(ch, block_id)

    # Update parent has_children
    parent["has_children"] = True
    parent["updated_at"] = now
    if parent.get("status") == "archived":
        parent["archived"] = True

    _save("blocks.json", blocks)

    # mark page search index stale
    sidx = _load("search_index.json")
    if not isinstance(sidx, list):
        sidx = []
    page_id = parent.get("page_id")
    srow = None
    for r in sidx:
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("object_type") == "page" and r.get("page_id") == page_id:
            srow = r
            break
    if srow:
        srow["status"] = "stale"
        srow["updated_at"] = now
        _save("search_index.json", sidx)

    resp = {"results": created, "has_more": False, "next_cursor": None, "total": len(created)}
    _log("ok", workspace=workspace_id, meta={"created": len(created), "parent_block_id": block_id})
    return resp

