        blk = None
        for r in blocks:
            if isinstance(r, dict) and r.get("id") == block_id:
                blk = r
                break
        if not blk:
            _log("error", None, error_code="NOT_FOUND", meta={"block_id": block_id})
            return _err("NOT_FOUND", "Block not found", block_id=block_id)

        workspace_id = blk.get("workspace_id")
        ok, rlerr = _rate_limit_check(workspace_id)
        if not ok:
            _log("error", workspace_id, error_code=rlerr["error"]["code"])
            return rlerr

        if blk.get("status") in ("archived", "deleted") or blk.get("archived") is True:
            _log("error", workspace_id, error_code="CONFLICT", meta={"block_id": block_id})
            return _err("CONFLICT", "Block is archived or deleted and cannot be updated", block_id=block_id)

        # type cannot be changed in Notion-like model
        if type is not None and type != blk.get("type"):
            _log("error", workspace_id, error_code="CONFLICT", meta={"block_id": block_id})
            return _err("CONFLICT", "Block type cannot be changed", block_id=block_id)

        # validate some type-specific invariants
        if data is not None:
            btype = blk.get("type")
            if btype == "to_do":
                if "checked" in data and not isinstance(data.get("checked"), bool):
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "data.checked"})
                    return _err("VALIDATION_ERROR", "to_do.checked must be a boolean", field="data.checked")
            if btype == "code":
                if "language" in data and not isinstance(data.get("language"), str):
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "data.language"})
                    return _err("VALIDATION_ERROR", "code.language must be a string", field="data.language")
            if btype in ("bookmark", "image", "file"):
                if "url" in data and not isinstance(data.get("url"), str):
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "data.url"})
                    return _err("VALIDATION_ERROR", "data.url must be a string", field="data.url")

        before = json.dumps(blk, sort_keys=True, default=str)
        if archived is not None:
            # map archived boolean to lifecycle status transition
            cur = blk.get("status")
            desired = "archived" if archived else "active"
            if desired != cur:
                allowed = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
                if cur not in allowed or desired not in allowed[cur]:
                    _log("error", workspace_id, error_code="INVALID_TRANSITION", meta={"from": cur, "to": desired})
                    return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {desired}", from_status=cur, to_status=desired)
                blk["status"] = desired
            blk["archived"] = bool(archived)
        if has_children is not None:
            blk["has_children"] = bool(has_children)
        if data is not None:
            # merge data (server-style update)
            curd = blk.get("data")
            if not isinstance(curd, dict):
                curd = {}
            curd.update(data)
            blk["data"] = curd

        blk["updated_at"] = _now()
        after = json.dumps(blk, sort_keys=True, default=str)
        if after == before:
            _log("error", workspace_id, error_code="CONFLICT", meta={"block_id": block_id})
            return _err("CONFLICT", "Update made no changes", block_id=block_id)

        _save("blocks.json", blocks)

        # mark page search index stale
        page_id = blk.get("page_id")
        if isinstance(page_id, str):
            # find page to get workspace and ensure exists
            page = None
            for p in pages:
                if isinstance(p, dict) and p.get("id") == page_id:
                    page = p
                    break
            if page is not None:
                idx = None
                for r in sidx:
                    if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("object_type") == "page" and r.get("page_id") == page_id:
                        idx = r
                        break
                now = _now()
                if idx is not None:
                    if idx.get("status") != "disabled":
                        idx["status"] = "stale"
                    idx["updated_at"] = now
                    _save("search_index.json", sidx)

        _log("ok", workspace_id, meta={"block_id": block_id})
        return {"object": "block", "block": blk}
    except Exception as e:
        _log("error", None, error_code="VALIDATION_ERROR", meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def search(query=None, filter=None, sort=None, page_size=None, start_cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "search",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        # search quota tends to be tighter; 120/min
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    # Accept empty args => return empty results (audit expects no error)
    if query is None:
        sidx = _load("search_index.json")
        if not isinstance(sidx, list):
            sidx = []
        # pick a workspace for logging if any
        ws = None
        for r in sidx:
            if isinstance(r, dict) and r.get("workspace_id"):
                ws = r.get("workspace_id")
                break
        _log("ok", workspace=ws, meta={"returned": 0, "total": 0})
        return {"results": [], "has_more": False, "next_cursor": None, "total": 0}

    if not isinstance(query, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "query"})
        return _err("VALIDATION_ERROR", "query must be a string.", field="query")
    q = query.strip().lower()
    if not q:
        _log("ok", meta={"returned": 0, "total": 0})
        return {"results": [], "has_more": False, "next_cursor": None, "total": 0}

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.", field="page_size")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")

    f_object_type = None
    f_workspace_id = None
    f_status = None
    if filter is not None:
        if not isinstance(filter, dict):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter"})
            return _err("VALIDATION_ERROR", "filter must be an object.", field="filter")
        f_object_type = filter.get("object_type")
        if f_object_type is not None and f_object_type not in ("page", "database"):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter.object_type"})
            return _err("VALIDATION_ERROR", "filter.object_type must be 'page' or 'database'.", field="filter.object_type")
        f_workspace_id = filter.get("workspace_id")
        if f_workspace_id is not None and not isinstance(f_workspace_id, str):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter.workspace_id"})
            return _err("VALIDATION_ERROR", "filter.workspace_id must be a string.", field="filter.workspace_id")
        f_status = filter.get("status")
        if f_status is not None and f_status not in ("ready", "stale", "disabled"):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter.status"})
            return _err("VALIDATION_ERROR", "filter.status must be one of: ready, stale, disabled.", field="filter.status")

    sort_ts = None
    sort_dir = "desc"
    if sort is not None:
        if not isinstance(sort, dict):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort"})
            return _err("VALIDATION_ERROR", "sort must be an object.", field="sort")
        sort_ts = sort.get("timestamp")
        if sort_ts not in ("last_indexed_at", "updated_at", "created_at"):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort.timestamp"})
            return _err("VALIDATION_ERROR", "sort.timestamp must be one of: last_indexed_at, updated_at, created_at.", field="sort.timestamp")
        if sort.get("direction") is not None:
            if sort.get("direction") not in ("asc", "desc"):
                _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort.direction"})
                return _err("VALIDATION_ERROR", "sort.direction must be asc or desc.", field="sort.direction")
            sort_dir = sort.get("direction")

    sidx = _load("search_index.json")
    if not isinstance(sidx, list):
        sidx = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    # Determine ambient workspace for rate limiting: prefer filter.workspace_id; else choose any matching row later
    ws_for_rl = f_workspace_id
    if ws_for_rl is None:
        for r in sidx:
            if isinstance(r, dict) and r.get("workspace_id"):
                ws_for_rl = r.get("workspace_id")
                break
    ok, rlmeta = _rate_limit_check(ws_for_rl)
    if not ok:
        _log("error", workspace=ws_for_rl, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    def _matches_text(r):
        t = (r.get("title_text") or "")
        c = (r.get("content_text") or "")
        return q in str(t).lower() or q in str(c).lower()

    hits = []
    for r in sidx:
        if not isinstance(r, dict):
            continue
        if f_workspace_id is not None and r.get("workspace_id") != f_workspace_id:
            continue
        if f_object_type is not None and r.get("object_type") != f_object_type:
            continue
        if f_status is not None and r.get("status") != f_status:
            continue
        if not _matches_text(r):
            continue

        # resolve referenced object and exclude deleted; typically exclude archived
        obj = None
        if r.get("object_type") == "page":
            pid = r.get("page_id")
            obj = next((p for p in pages if isinstance(p, dict) and p.get("id") == pid), None)
            if not obj or obj.get("status") == "deleted":
                continue
            if obj.get("status") == "archived":
                continue
        elif r.get("object_type") == "database":
            did = r.get("database_id")
            obj = next((d for d in dbs if isinstance(d, dict) and d.get("id") == did), None)
            if not obj or obj.get("status") == "deleted":
                continue
            if obj.get("status") == "archived":
                continue
        else:
            continue

        hits.append({"object": obj, "search_index": r})

    # sorting
    if sort_ts is None:
        sort_ts = "last_indexed_at"
    reverse = (sort_dir == "desc")

    def _sort_key(item):
        r = item.get("search_index") or {}
        dt = _parse_dt(r.get(sort_ts) or "")
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, (r.get("id") or ""))

    hits.sort(key=_sort_key, reverse=reverse)

    # cursor: "v1:<sort_ts>:<timestamp>:<search_index_id>"
    start_idx = 0
    if start_cursor:
        if not start_cursor.startswith("v1:"):
            _log("error", workspace=ws_for_rl, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        parts = start_cursor.split(":", 3)
        if len(parts) != 4:
            _log("error", workspace=ws_for_rl, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        _, c_ts, c_val, c_id = parts
        if c_ts != sort_ts:
            _log("error", workspace=ws_for_rl, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        cdt = _parse_dt(c_val)
        if cdt is None:
            _log("error", workspace=ws_for_rl, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")

        def _after(item):
            r = item.get("search_index") or {}
            dt = _parse_dt(r.get(sort_ts) or "")
            if dt is None:
                return False
            tup = (dt, r.get("id") or "")
            ctup = (cdt, c_id)
            return tup < ctup if reverse else tup > ctup

        for i, it in enumerate(hits):
            if _after(it):
                start_idx = i
                break
        else:
            start_idx = len(hits)

    page = hits[start_idx:start_idx + page_size]
    has_more = (start_idx + page_size) < len(hits)
    next_cursor = None
    if has_more and page:
        last = page[-1]["search_index"]
        next_cursor = f"v1:{sort_ts}:{last.get(sort_ts) or ''}:{last.get('id') or ''}"

    results = [it["object"] for it in page]
    _log("ok", workspace=ws_for_rl, meta={"returned": len(results), "total": len(hits)})
    return {"results": results, "has_more": has_more, "next_cursor": next_cursor, "total": len(hits)}

def get_comments(**_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "get-comments",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    # Accept empty args => return empty set (audit expects no error)
    page_id = _extra.get("page_id") or _extra.get("pageId")
    block_id = _extra.get("block_id") or _extra.get("blockId")
    discussion_id = _extra.get("discussion_id") or _extra.get("discussionId")
    page_size = _extra.get("page_size") or _extra.get("pageSize")
    start_cursor = _extra.get("start_cursor") or _extra.get("startCursor")
    include_deleted = _extra.get("include_deleted") or _extra.get("includeDeleted")

    if page_id is None and block_id is None and discussion_id is None:
        _log("ok", meta={"returned": 0, "total": 0})
        return {"results": [], "has_more": False, "next_cursor": None, "total": 0}

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "include_deleted"})
        return _err("VALIDATION_ERROR", "include_deleted must be boolean.", field="include_deleted")

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []
    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    blocks = _load("blocks.json")
    if not isinstance(blocks, list):
        blocks = []

    workspace_id = None
    if page_id is not None:
        if not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-Z]{4,}$", page_id):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_id"})
            return _err("VALIDATION_ERROR", "page_id is malformed.", field="page_id")
        page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id and p.get("status") != "deleted"), None)
        if not page:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Page not found.")
        workspace_id = page.get("workspace_id")

    if block_id is not None:
        if not isinstance(block_id, str) or not re.match(r"^ntn_blk_[0-9A-Z]{4,}$", block_id):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "block_id"})
            return _err("VALIDATION_ERROR", "block_id is malformed.", field="block_id")
        blk = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id and b.get("status") != "deleted"), None)
        if not blk:
            _log("error", workspace=workspace_id, meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Block not found.")
        if page_id is not None and blk.get("page_id") != page_id:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "block_id does not belong to page_id.")
        if workspace_id is None:
            # resolve via page
            p = next((p for p in pages if isinstance(p, dict) and p.get("id") == blk.get("page_id")), None)
            workspace_id = p.get("workspace_id") if p else blk.get("workspace_id")

    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    # Filter by target
    out = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if workspace_id is not None and c.get("workspace_id") != workspace_id:
            continue
        if page_id is not None and c.get("page_id") != page_id:
            continue
        if block_id is not None and c.get("block_id") != block_id:
            continue
        if discussion_id is not None and c.get("discussion_id") != discussion_id:
            continue
        if not include_deleted and c.get("status") != "published":
            continue
        out.append(c)

    # order: created_at asc within discussion (and overall)
    out.sort(key=lambda c: (c.get("discussion_id") or "", _parse_dt(c.get("created_at") or "") or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), c.get("id") or ""))

    # cursor: "v1:<created_at>:<id>"
    start_idx = 0
    if start_cursor:
        if not start_cursor.startswith("v1:"):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        parts = start_cursor.split(":", 2)
        if len(parts) != 3:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        _, c_ts, c_id = parts
        cdt = _parse_dt(c_ts)
        if cdt is None:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        for i, c in enumerate(out):
            dt = _parse_dt(c.get("created_at") or "")
            if dt is None:
                continue
            if (dt, c.get("id") or "") > (cdt, c_id):
                start_idx = i
                break
        else:
            start_idx = len(out)

    page = out[start_idx:start_idx + page_size]
    has_more = (start_idx + page_size) < len(out)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"v1:{last.get('created_at') or ''}:{last.get('id') or ''}"

    _log("ok", workspace=workspace_id, meta={"returned": len(page), "total": len(out)})
    return {"results": page, "has_more": has_more, "next_cursor": next_cursor, "total": len(out)}

def get_all_page_comments(**_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "get-all-page-comments",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    page_id = _extra.get("page_id") or _extra.get("pageId")
    page_size = _extra.get("page_size") or _extra.get("pageSize")
    start_cursor = _extra.get("start_cursor") or _extra.get("startCursor")
    include_deleted = _extra.get("include_deleted") or _extra.get("includeDeleted")

    # If called with empty args, return empty set (audit expects no error)
    if page_id is None:
        _log("ok", meta={"returned": 0, "total": 0})
        return {"results": [], "has_more": False, "next_cursor": None, "total": 0}

    if not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-Z]{4,}$", page_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_id"})
        return _err("VALIDATION_ERROR", "page_id is malformed.", field="page_id")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "include_deleted"})
        return _err("VALIDATION_ERROR", "include_deleted must be boolean.", field="include_deleted")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id and p.get("status") != "deleted"), None)
    if not page:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Page not found.")

    workspace_id = page.get("workspace_id")
    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    blocks = _load("blocks.json")
    if not isinstance(blocks, list):
        blocks = []
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    # Build set of valid block ids for this page (for block-level comments)
    block_ids = {b.get("id") for b in blocks if isinstance(b, dict) and b.get("page_id") == page_id and b.get("status") != "deleted"}

    out = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("page_id") != page_id:
            continue
        bid = c.get("block_id")
        if bid is not None and bid not in block_ids:
            # enforce rule: block_id must reference block with same page_id
            continue
        if not include_deleted and c.get("status") != "published":
            continue
        out.append(c)

    out.sort(key=lambda c: (_parse_dt(c.get("created_at") or "") or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), c.get("discussion_id") or "", c.get("id") or ""))

    start_idx = 0
    if start_cursor:
        if not start_cursor.startswith("v1:"):
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        parts = start_cursor.split(":", 2)
        if len(parts) != 3:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        _, c_ts, c_id = parts
        cdt = _parse_dt(c_ts)
        if cdt is None:
            _log("error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR", "field": "start_cursor"})
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")
        for i, c in enumerate(out):
            dt = _parse_dt(c.get("created_at") or "")
            if dt is None:
                continue
            if (dt, c.get("id") or "") > (cdt, c_id):
                start_idx = i
                break
        else:
            start_idx = len(out)

    page_out = out[start_idx:start_idx + page_size]
    has_more = (start_idx + page_size) < len(out)
    next_cursor = None
    if has_more and page_out:
        last = page_out[-1]
        next_cursor = f"v1:{last.get('created_at') or ''}:{last.get('id') or ''}"

    _log("ok", workspace=workspace_id, meta={"returned": len(page_out), "total": len(out)})
    return {"results": page_out, "has_more": has_more, "next_cursor": next_cursor, "total": len(out)}

def create_comment(**_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_str, workspace=None, meta=None, error_code=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "create-comment",
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        if not workspace:
            return True, None
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            dt = _parse_dt(r.get("timestamp") or r.get("ts"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=60, workspace_id=workspace)
        return True, None

    try:
        # Vendor tool schema omitted; accept typical Notion-like parameters from _extra
        page_id = _extra.get("page_id")
        block_id = _extra.get("block_id")
        discussion_id = _extra.get("discussion_id") or _extra.get("discussionId")
        rich_text = _extra.get("rich_text")

        if page_id is None and block_id is None:
            _log("error", None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either page_id or block_id must be provided", rule="create-comment target identifiers")

        if page_id is not None and (not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", page_id)):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "page_id"})
            return _err("VALIDATION_ERROR", "page_id is malformed", field="page_id")
        if block_id is not None and (not isinstance(block_id, str) or not re.match(r"^ntn_blk_[0-9A-HJKMNP-TV-Z]{10,}$", block_id)):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "block_id"})
            return _err("VALIDATION_ERROR", "block_id is malformed", field="block_id")

        # allow empty array but require array type (audit defect: missing param should be surfaced clearly)
        if rich_text is None or not isinstance(rich_text, list):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "rich_text"})
            return _err("VALIDATION_ERROR", "rich_text must be a JSON array", field="rich_text", rule="rich_text must be a JSON array (possibly empty but typically non-empty)")

        if discussion_id is not None and (not isinstance(discussion_id, str) or discussion_id.strip() == ""):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "discussion_id"})
            return _err("VALIDATION_ERROR", "discussion_id must be a non-empty string", field="discussion_id", rule="discussion_id <> ''")

        pages = _load("pages.json")
        if not isinstance(pages, list):
            pages = []
        blocks = _load("blocks.json")
        if not isinstance(blocks, list):
            blocks = []
        comments = _load("comments.json")
        if not isinstance(comments, list):
            comments = []

        target_page = None
        target_block = None

        if block_id is not None:
            for b in blocks:
                if isinstance(b, dict) and b.get("id") == block_id:
                    target_block = b
                    break
            if not target_block:
                _log("error", None, error_code="NOT_FOUND", meta={"block_id": block_id})
                return _err("NOT_FOUND", "Block not found", block_id=block_id)
            blk_page_id = target_block.get("page_id")
            if page_id is not None and page_id != blk_page_id:
                _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "page_id"})
                return _err("VALIDATION_ERROR", "page_id must match the block's page_id", field="page_id", rule="if block_id is provided, page_id must match the block's page_id")
            page_id = blk_page_id

        for p in pages:
            if isinstance(p, dict) and p.get("id") == page_id:
                target_page = p
                break
        if not target_page:
            _log("error", None, error_code="NOT_FOUND", meta={"page_id": page_id})
            return _err("NOT_FOUND", "Page not found", page_id=page_id)

        workspace_id = target_page.get("workspace_id")
        ok, rlerr = _rate_limit_check(workspace_id)
        if not ok:
            _log("error", workspace_id, error_code=rlerr["error"]["code"])
            return rlerr

        # if discussion_id provided, must exist on same page
        parent_comment_id = None
        if discussion_id is not None:
            exists = False
            for c in comments:
                if isinstance(c, dict) and c.get("discussion_id") == discussion_id and c.get("page_id") == page_id:
                    exists = True
                    break
            if not exists:
                _log("error", workspace_id, error_code="NOT_FOUND", meta={"discussion_id": discussion_id})
                return _err("NOT_FOUND", "discussion_id not found for this page", discussion_id=discussion_id, page_id=page_id)
        else:
            # generate new thread id
            discussion_id = f"ntn_disc_{int(time.time()*1000)}_{random.randint(1000, 9999)}"

        # determine parent_comment_id if replying: if discussion_id exists and caller supplied parent_comment_id in extras
        if _extra.get("parent_comment_id") is not None:
            pcid = _extra.get("parent_comment_id")
            if not isinstance(pcid, str) or not re.match(r"^ntn_cmt_[0-9A-HJKMNP-TV-Z]{10,}$", pcid):
                _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "parent_comment_id"})
                return _err("VALIDATION_ERROR", "parent_comment_id is malformed", field="parent_comment_id")
            pc = None
            for c in comments:
                if isinstance(c, dict) and c.get("id") == pcid:
                    pc = c
                    break
            if not pc or pc.get("discussion_id") != discussion_id or pc.get("page_id") != page_id:
                _log("error", workspace_id, error_code="NOT_FOUND", meta={"parent_comment_id": pcid})
                return _err("NOT_FOUND", "parent_comment_id not found in this discussion", parent_comment_id=pcid)
            parent_comment_id = pcid

        now = _now()
        new_id = f"ntn_cmt_{int(time.time()*1000)}_{os.getpid()}_{len(comments)+1}"
        row = {
            "id": new_id,
            "workspace_id": workspace_id,
            "discussion_id": discussion_id,
            "page_id": page_id,
            "block_id": block_id,
            "parent_comment_id": parent_comment_id,
            "author_user_id": None,
            "rich_text": rich_text,
            "status": "published",
            "created_at": now,
            "updated_at": now,
        }
        comments.append(row)
        _save("comments.json", comments)

        _log("ok", workspace_id, meta={"comment_id": new_id, "page_id": page_id, "discussion_id": discussion_id})
        return {"object": "comment", "comment": row}
    except Exception as e:
        _log("error", None, error_code="VALIDATION_ERROR", meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def get_database(database_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"

    def _log(status, workspace=None, meta=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "get-database",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list) or not workspace:
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            ts = r.get("timestamp") or r.get("ts")
            dt = _parse_dt(ts)
            if dt is not None and dt.replace(tzinfo=None) >= cutoff:
                cnt += 1
        if cnt >= 120:
            return False, {"limit": 120, "window_seconds": 60, "workspace_id": workspace}
        return True, None

    if not isinstance(database_id, str) or not re.match(r"^ntn_db_[0-9A-HJKMNP-TV-Z]{10,}$", database_id):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "database_id"})
        return _err("VALIDATION_ERROR", "database_id is malformed.", field="database_id")

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []
    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db or db.get("status") == "deleted":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Database not found.")

    workspace_id = db.get("workspace_id")
    ok, rlmeta = _rate_limit_check(workspace_id)
    if not ok:
        _log("error", workspace=workspace_id, meta={"code": "RATE_LIMIT", **(rlmeta or {})})
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rlmeta or {}))

    _log("ok", workspace=workspace_id, meta={"database_id": database_id})
    return db

def get_page(page_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, workspace_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "service": "notion",
            "endpoint": "get-page",
            "method": "GET",
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(workspace_id):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list): limits = []
        rules = [r for r in limits if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("endpoint") in (None, "get-page", "*")]
        if not rules:
            return True, None
        def _spec(r):
            ep = r.get("endpoint")
            return 2 if ep == "get-page" else (1 if ep == "*" else 0)
        rule = sorted(rules, key=_spec, reverse=True)[0]
        limit = rule.get("limit_per_minute")
        if not isinstance(limit, int) or limit <= 0:
            return True, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("endpoint") != "get-page":
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit_per_minute": limit}
        return True, None

    # Validate input
    if not isinstance(page_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id must be a string.")
    if not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", page_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is malformed.", field="page_id")

    pages = _load("pages.json")
    if not isinstance(pages, list): pages = []
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id), None)
    if page is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Page not found.")

    # Notion-like behavior: deleted pages are not retrievable
    if page.get("status") == "deleted":
        _log("NOT_FOUND", workspace_id=page.get("workspace_id"))
        return _err("NOT_FOUND", "Page not found.")

    workspace_id = page.get("workspace_id")
    if not isinstance(workspace_id, str) or not workspace_id:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized workspace context available to serve this request.")

    ok, rl = _rate_limit_ok(workspace_id)
    if not ok:
        _log("RATE_LIMIT", workspace_id=workspace_id, extra=rl)
        return _err("RATE_LIMIT", "Rate limit exceeded.", **(rl or {}))

    # In this datastore-backed implementation, workspace match is the access boundary.
    # Since the call has no explicit credential parameter and no auth collections are provided,
    # we cannot distinguish FORBIDDEN vs NOT_FOUND beyond workspace visibility.
    _log("OK", workspace_id=workspace_id)

    # Return metadata/properties only (no blocks expansion)
    return {
        "object": "page",
        "page": page
    }

def update_page(page_id, properties=None, title=None, icon=None, cover=None, archived=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0111000" if __import__("os").path.isdir("./environment_mix/0111000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _pick_logfile():
        for fn in ("request_log.json", "request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_log.json"
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None
    def _log(status_str, workspace=None, meta=None, error_code=None):
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "notion",
            "endpoint": "update-page",
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "credential_id": None,
            "workspace_id": workspace,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(workspace):
        if not workspace:
            return True, None
        fn = _pick_logfile()
        logs = _load(fn)
        if not isinstance(logs, list):
            return True, None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace:
                continue
            dt = _parse_dt(r.get("timestamp") or r.get("ts"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=60, workspace_id=workspace)
        return True, None

    try:
        if not isinstance(page_id, str) or not re.match(r"^ntn_pg_[0-9A-HJKMNP-TV-Z]{10,}$", page_id):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "page_id"})
            return _err("VALIDATION_ERROR", "page_id is malformed", field="page_id")

        if properties is None and title is None and icon is None and cover is None and archived is None and status is None:
            _log("error", None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "No updatable fields provided")

        if properties is not None and not isinstance(properties, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "properties"})
            return _err("VALIDATION_ERROR", "properties must be a JSON object", field="properties", rule="properties must be valid JSON object")
        if title is not None and (not isinstance(title, str) or title.strip() == ""):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "title"})
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
        if icon is not None and not isinstance(icon, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "icon"})
            return _err("VALIDATION_ERROR", "icon must be a JSON object", field="icon")
        if cover is not None and not isinstance(cover, dict):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "cover"})
            return _err("VALIDATION_ERROR", "cover must be a JSON object", field="cover")
        if archived is not None and not isinstance(archived, bool):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "archived"})
            return _err("VALIDATION_ERROR", "archived must be a boolean", field="archived")
        if status is not None and status not in ("active", "archived", "deleted"):
            _log("error", None, error_code="VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

        pages = _load("pages.json")
        if not isinstance(pages, list):
            pages = []
        dbs = _load("databases.json")
        if not isinstance(dbs, list):
            dbs = []
        sidx = _load("search_index.json")
        if not isinstance(sidx, list):
            sidx = []

        page = None
        for p in pages:
            if isinstance(p, dict) and p.get("id") == page_id:
                page = p
                break
        if not page:
            _log("error", None, error_code="NOT_FOUND", meta={"page_id": page_id})
            return _err("NOT_FOUND", "Page not found", page_id=page_id)

        workspace_id = page.get("workspace_id")
        ok, rlerr = _rate_limit_check(workspace_id)
        if not ok:
            _log("error", workspace_id, error_code=rlerr["error"]["code"])
            return rlerr

        # Handle archived/status invariant. If both provided and inconsistent => error. Else derive.
        if archived is not None and status is not None:
            if archived != (status == "archived"):
                _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": "archived", "rule": "archived = (status = 'archived')"})
                return _err("VALIDATION_ERROR", "archived must equal (status == 'archived')", rule="archived = (status = 'archived')", field="archived")
        new_status = status if status is not None else ("archived" if archived is True else ("active" if archived is False else None))
        new_archived = archived if archived is not None else (True if status == "archived" else (False if status == "active" else None))

        # validate lifecycle transition
        if new_status is not None and new_status != page.get("status"):
            cur = page.get("status")
            allowed = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
            if cur not in allowed or new_status not in allowed[cur]:
                _log("error", workspace_id, error_code="INVALID_TRANSITION", meta={"from": cur, "to": new_status})
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {new_status}", from_status=cur, to_status=new_status)

        # database schema validation if page is in database
        if properties is not None and page.get("parent_type") == "database":
            dbid = page.get("parent_database_id")
            db = None
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == dbid and d.get("workspace_id") == workspace_id:
                    db = d
                    break
            if not db:
                _log("error", workspace_id, error_code="NOT_FOUND", meta={"parent_database_id": dbid})
                return _err("NOT_FOUND", "Parent database not found", database_id=dbid)
            schema = db.get("properties_schema")
            if not isinstance(schema, dict):
                _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"database_id": dbid})
                return _err("VALIDATION_ERROR", "Parent database has invalid properties_schema", database_id=dbid)
            # Ensure updates only touch known properties
            for k in properties.keys():
                if k not in schema:
                    _log("error", workspace_id, error_code="VALIDATION_ERROR", meta={"field": f"properties.{k}"})
                    return _err("VALIDATION_ERROR", "Unknown property for this database", field=f"properties.{k}", rule="validate properties against database schema")
            # Ensure title property exists after merge
            title_names = [k for k, v in schema.items() if isinstance(v, dict) and v.get("type") == "title"]
            merged = dict(page.get("properties") if isinstance(page.get("properties"), dict) else {})
            merged.update(properties)
            if title_names and not any(n in merged for n in title_names):
                _log("error", workspace_id, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Missing required title property for database page", rule="pages.properties must conform to databases.properties_schema")

        before = json.dumps(page, sort_keys=True, default=str)

        if properties is not None:
            curp = page.get("properties")
            if not isinstance(curp, dict):
                curp = {}
            curp.update(properties)
            page["properties"] = curp

        if title is not None:
            # Allow setting title for display/metadata even if parent is database (some APIs derive it; we accept and store).
            page["title"] = title

        if icon is not None:
            page["icon"] = icon
        if cover is not None:
            page["cover"] = cover
        if new_status is not None:
            page["status"] = new_status
        if new_archived is not None:
            page["archived"] = new_archived

        page["updated_at"] = _now()

        after = json.dumps(page, sort_keys=True, default=str)
        if after == before:
            _log("error", workspace_id, error_code="CONFLICT", meta={"page_id": page_id})
            return _err("CONFLICT", "Update made no changes", page_id=page_id)

        _save("pages.json", pages)

        # mark search index stale for this page
        idx = None
        for r in sidx:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("object_type") == "page" and r.get("page_id") == page_id:
                idx = r
                break
        now = _now()
        if idx is not None:
            if idx.get("status") != "disabled":
                idx["status"] = "stale"
            idx["updated_at"] = now
            _save("search_index.json", sidx)

        _log("ok", workspace_id, meta={"page_id": page_id})
        return {"object": "page", "page": page}
    except Exception as e:
        _log("error", None, error_code="VALIDATION_ERROR", meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
